#!/usr/bin/env python3
# Generated by Claudian.
"""Headless latency benchmark — no microphone, no wake word, no Ctrl-C.

`test_latency.py` needs a live mic and a KeyboardInterrupt to print anything,
so it can't run in CI or over SSH and can't produce a comparable number twice.
This measures the stages that don't need audio input, repeatably:

    intent routing (local matcher)   — pure CPU, should be ~0ms
    intent routing (LLM tie-break)   — Groq round trip
    conversation reply               — Groq round trip
    TTS synthesis                    — ElevenLabs or macOS `say`

Usage:
    python3 bench_latency.py                # everything
    python3 bench_latency.py --no-tts       # skip audio (silent run)
    python3 bench_latency.py --runs 5       # more samples
"""

from __future__ import annotations

import argparse
import statistics
import sys
import time
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))


def _p(label: str, samples: list[float], note: str = "") -> None:
    if not samples:
        print(f"  {label:<34} —      (skipped) {note}")
        return
    med = statistics.median(samples)
    lo, hi = min(samples), max(samples)
    flag = "🔴" if med > 1500 else "🟡" if med > 600 else "🟢"
    print(f"  {label:<34} {flag} {med:7.0f}ms   "
          f"(min {lo:.0f} / max {hi:.0f}, n={len(samples)}) {note}")


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--runs", type=int, default=3)
    ap.add_argument("--no-tts", action="store_true")
    ap.add_argument("--no-llm", action="store_true")
    args = ap.parse_args()

    print("\n" + "=" * 74)
    print("JARVIS headless latency baseline")
    print("=" * 74)

    from config import settings

    # Fail loudly rather than reporting a fast number that is really a fast
    # *failure*. A 401 makes every "LLM" stage look instant.
    if not args.no_llm and settings.GROQ_API_KEY:
        try:
            from openai import OpenAI
            OpenAI(api_key=settings.GROQ_API_KEY,
                   base_url="https://api.groq.com/openai/v1"
                   ).chat.completions.create(
                model=settings.GROQ_CHAT_MODEL,
                messages=[{"role": "user", "content": "ok"}],
                max_tokens=2, timeout=15)
        except Exception as exc:
            print(f"\n  ⚠️  GROQ IS NOT ANSWERING — {type(exc).__name__}")
            print(f"      {str(exc)[:160]}")
            print("      LLM timings below are failure paths, not real "
                  "round trips.\n")

    print(f"  chat model : {settings.GROQ_CHAT_MODEL}")
    print(f"  fast model : {settings.GROQ_FAST_MODEL}")
    print(f"  TTS engine : {settings.TTS_ENGINE}")
    print(f"  STT engine : {settings.STT_ENGINE}")
    print("-" * 74)

    # ── Stage 1: local intent matching (no network) ──────────────────────
    from skills._registry import get_registry
    registry = get_registry()

    phrases = ["open chrome", "what time is it", "volume 50",
               "take a screenshot", "what's my battery"]
    local: list[float] = []
    for _ in range(args.runs):
        for phrase in phrases:
            t0 = time.perf_counter()
            for skill in registry.all_skills():
                skill.match(phrase)
            local.append((time.perf_counter() - t0) * 1000)

    # ── Stage 2 + 3: LLM round trips ─────────────────────────────────────
    llm_intent: list[float] = []
    llm_chat: list[float] = []

    if not args.no_llm and settings.has_ai():
        from ai.memory import ConversationMemory
        from ai.conversation_engine import ConversationEngine

        engine = ConversationEngine(ConversationMemory())
        for _ in range(args.runs):
            t0 = time.perf_counter()
            engine.chat("say the single word: ready")
            llm_chat.append((time.perf_counter() - t0) * 1000)

        try:
            from ai.intent_classifier import IntentClassifier
            clf = IntentClassifier(registry)
            for _ in range(args.runs):
                t0 = time.perf_counter()
                clf.classify("dim the screen a bit")
                llm_intent.append((time.perf_counter() - t0) * 1000)
        except Exception as exc:
            print(f"  (intent classifier unavailable: {exc})")

    # ── Stage 4: TTS synthesis ───────────────────────────────────────────
    tts: list[float] = []
    if not args.no_tts:
        try:
            from voice.text_to_speech import TextToSpeech
            speaker = TextToSpeech()
            for _ in range(args.runs):
                t0 = time.perf_counter()
                speaker.speak("Ready.")
                tts.append((time.perf_counter() - t0) * 1000)
        except Exception as exc:
            print(f"  (TTS unavailable: {exc})")

    # ── Report ────────────────────────────────────────────────────────────
    print("\nSTAGE LATENCY (median)")
    _p("local intent match (28 skills)", local, "← pure CPU")
    _p("LLM intent tie-break", llm_intent, "← Groq")
    _p("LLM conversation reply", llm_chat, "← Groq")
    _p("TTS synthesis (blocking call)", tts, f"← {settings.TTS_ENGINE}")

    print("-" * 74)
    fast = statistics.median(local) if local else 0
    slow = (statistics.median(llm_chat) if llm_chat else 0)
    print(f"  Skill command (no LLM)   ≈ {fast:.0f}ms")
    print(f"  Conversation (with LLM)  ≈ {fast + slow:.0f}ms")
    print("\n  Note: excludes STT and wake-word detection, which need a mic.")
    print("  Run before and after a change to see whether it actually helped.")
    print("=" * 74 + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())
